head.script:
(function(){
  const NS="http://www.w3.org/1999/xhtml";
  const root=document.querySelector("foreignObject").firstElementChild;
  const head=root.querySelector("head");
  const body=root.querySelector("body");
  const origCE=document.createElement.bind(document);
  const origCENS=document.createElementNS.bind(document);
  Object.defineProperty(document,"head",{get(){return head;},configurable:true});
  Object.defineProperty(document,"body",{get(){return body;},configurable:true});
  Object.defineProperty(document,"documentElement",{get(){return root;},configurable:true});
  document.createElement=function(t,o){return typeof t==="string"?origCENS(NS,t,o):origCE(t,o);};
  document.createElementNS=function(ns,q,o){return(ns==null||ns===NS)?origCENS(NS,q,o):origCENS(ns,q,o);};
})();

body.script:
// ── Geometric particle background ──────────────────────────────
const canvas = document.getElementById("geo");
const ctx = canvas.getContext("2d");
let W, H, mouse = {x: -9999, y: -9999};
const SHAPES = [];
const COUNT = 38;
const REPEL_DIST = 130;
const REPEL_FORCE = 2.8;

const ACCENT = "rgba(41,68,217,";
const DIM    = "rgba(80,100,200,";

function resize(){
  W = canvas.width  = window.innerWidth;
  H = canvas.height = window.innerHeight;
}
resize();
window.addEventListener("resize", resize);

window.addEventListener("mousemove", e => {
  mouse.x = e.clientX;
  mouse.y = e.clientY;
});
window.addEventListener("touchmove", e => {
  const t = e.touches[0];
  mouse.x = t.clientX;
  mouse.y = t.clientY;
}, {passive: true});
window.addEventListener("touchend", () => {
  mouse.x = -9999; mouse.y = -9999;
}, {passive: true});

const TYPES = ["tri","quad","hex","ring","cross"];

function randBetween(a,b){ return a + Math.random()*(b-a); }

function makeShape(){
  const type = TYPES[Math.floor(Math.random()*TYPES.length)];
  const size = randBetween(10, 36);
  return {
    type,
    x: randBetween(0, W || 1200),
    y: randBetween(0, H || 800),
    vx: randBetween(-0.3, 0.3),
    vy: randBetween(-0.3, 0.3),
    size,
    rot: randBetween(0, Math.PI*2),
    rotV: randBetween(-0.004, 0.004),
    alpha: randBetween(0.08, 0.32),
    alphaDir: Math.random()>0.5?1:-1,
    fill: Math.random()>0.6
  };
}

for(let i=0;i<COUNT;i++) SHAPES.push(makeShape());

function drawTri(c, s, rot, alpha, fill){
  c.save(); c.rotate(rot);
  c.beginPath();
  for(let i=0;i<3;i++){
    const a = (Math.PI*2/3)*i - Math.PI/2;
    i===0?c.moveTo(Math.cos(a)*s,Math.sin(a)*s):c.lineTo(Math.cos(a)*s,Math.sin(a)*s);
  }
  c.closePath();
  if(fill){ c.fillStyle=ACCENT+(alpha*0.4)+")"; c.fill(); }
  c.strokeStyle=ACCENT+alpha+")"; c.lineWidth=1; c.stroke();
  c.restore();
}

function drawQuad(c, s, rot, alpha, fill){
  c.save(); c.rotate(rot);
  c.beginPath();
  c.rect(-s/2,-s/2,s,s);
  if(fill){ c.fillStyle=ACCENT+(alpha*0.35)+")"; c.fill(); }
  c.strokeStyle=ACCENT+alpha+")"; c.lineWidth=1; c.stroke();
  c.restore();
}

function drawHex(c, s, rot, alpha, fill){
  c.save(); c.rotate(rot);
  c.beginPath();
  for(let i=0;i<6;i++){
    const a=(Math.PI/3)*i;
    i===0?c.moveTo(Math.cos(a)*s,Math.sin(a)*s):c.lineTo(Math.cos(a)*s,Math.sin(a)*s);
  }
  c.closePath();
  if(fill){ c.fillStyle=DIM+(alpha*0.3)+")"; c.fill(); }
  c.strokeStyle=DIM+alpha+")"; c.lineWidth=1; c.stroke();
  c.restore();
}

function drawRing(c, s, rot, alpha){
  c.save(); c.rotate(rot);
  c.beginPath();
  c.arc(0,0,s,0,Math.PI*2);
  c.strokeStyle=ACCENT+alpha+")"; c.lineWidth=1; c.stroke();
  c.beginPath();
  c.arc(0,0,s*0.55,0,Math.PI*2);
  c.strokeStyle=ACCENT+(alpha*0.5)+")"; c.lineWidth=0.8; c.stroke();
  c.restore();
}

function drawCross(c, s, rot, alpha){
  c.save(); c.rotate(rot);
  const arm=s*0.9, w=s*0.22;
  c.beginPath();
  c.rect(-w/2,-arm/2,w,arm);
  c.rect(-arm/2,-w/2,arm,w);
  c.fillStyle=ACCENT+(alpha*0.5)+")"; c.fill();
  c.restore();
}

function drawShape(shape){
  ctx.save();
  ctx.translate(shape.x, shape.y);
  const {type,size,rot,alpha,fill} = shape;
  if(type==="tri")   drawTri(ctx,size,rot,alpha,fill);
  else if(type==="quad") drawQuad(ctx,size,rot,alpha,fill);
  else if(type==="hex")  drawHex(ctx,size,rot,alpha,fill);
  else if(type==="ring") drawRing(ctx,size,rot,alpha);
  else if(type==="cross") drawCross(ctx,size,rot,alpha);
  ctx.restore();
}

function drawGrid(){
  const step=80;
  ctx.strokeStyle="rgba(41,68,217,0.04)";
  ctx.lineWidth=0.5;
  for(let x=0;x<W;x+=step){
    ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,H); ctx.stroke();
  }
  for(let y=0;y<H;y+=step){
    ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(W,y); ctx.stroke();
  }
}

function tick(){
  ctx.clearRect(0,0,W,H);
  drawGrid();

  for(const s of SHAPES){
    const dx = s.x - mouse.x;
    const dy = s.y - mouse.y;
    const dist = Math.sqrt(dx*dx+dy*dy);
    if(dist < REPEL_DIST && dist > 0){
      const force = (1 - dist/REPEL_DIST) * REPEL_FORCE;
      s.vx += (dx/dist)*force*0.12;
      s.vy += (dy/dist)*force*0.12;
    }

    s.vx *= 0.97;
    s.vy *= 0.97;

    const speed = Math.sqrt(s.vx*s.vx+s.vy*s.vy);
    if(speed > 3){ s.vx=(s.vx/speed)*3; s.vy=(s.vy/speed)*3; }

    s.x += s.vx;
    s.y += s.vy;
    s.rot += s.rotV;

    const pad = s.size + 4;
    if(s.x < pad){ s.x = pad; s.vx = Math.abs(s.vx)*0.6; }
    if(s.x > W-pad){ s.x = W-pad; s.vx = -Math.abs(s.vx)*0.6; }
    if(s.y < pad){ s.y = pad; s.vy = Math.abs(s.vy)*0.6; }
    if(s.y > H-pad){ s.y = H-pad; s.vy = -Math.abs(s.vy)*0.6; }

    s.alpha += s.alphaDir * 0.001;
    if(s.alpha > 0.38){ s.alphaDir=-1; }
    if(s.alpha < 0.06){ s.alphaDir=1; }

    drawShape(s);
  }

  requestAnimationFrame(tick);
}
tick();

// ── Menu items ──────────────────────────────────────────────────
const menuItems=[
  {label:"Yuki OS",url:"https://quantil.jsdelivr.net/gh/reeyuki/YukiOsSingleHtml@main/yukios.svg"},
  {label:"Lucide",url:"https://cdn.jsdelivr.net/gh/lucideproxy/svg@latest/logo.svg#/"},
  {label:"Petezah",url:"https://originfastly.jsdelivr.net/gh/PeteZah-G/PeteZahStaticDone@959d81f/new.svg"},
  {label:"Nikehub",url:"https://cdn.jsdelivr.net/gh/avaisadev/github.com@latest/index.svg"},
  {label:"Fern",url:"https://d1w7oj52hl4x53.cloudfront.net/"}
];
const menuBody=document.getElementById("menu-buttons");
menuItems.forEach(item=>{
  const btn=document.createElement("button");
  btn.className="menu-btn";
  btn.textContent=item.label;
  btn.onclick=()=>{
    const win=window.open("about:blank","_blank");
    if(!win)return;
    const iframe=win.document.createElement("iframe");
    iframe.src=item.url;
    iframe.style.cssText="position:fixed;inset:0;width:100vw;height:100vh;border:none;";
    win.document.body.style.margin="0";
    win.document.body.appendChild(iframe);
  };
  menuBody.appendChild(btn);
});

// ── Clock ───────────────────────────────────────────────────────
function updateClock(){
  const now=new Date();
  const h=String(now.getHours()).padStart(2,"0");
  const m=String(now.getMinutes()).padStart(2,"0");
  const s=String(now.getSeconds()).padStart(2,"0");
  document.getElementById("clock").textContent=h+":"+m+":"+s;
}
setInterval(updateClock,1000);
updateClock();

// ── Battery ─────────────────────────────────────────────────────
async function initBattery(){
  if(!navigator.getBattery)return;
  const bat=await navigator.getBattery();
  function render(){
    const pct=Math.round(bat.level*100);
    document.getElementById("battery-text").textContent=pct+"%";
    document.getElementById("battery-fill").style.width=pct+"%";
  }
  render();
  bat.addEventListener("levelchange",render);
}

// ── IP ──────────────────────────────────────────────────────────
async function fetchIP(){
  try{
    const r=await fetch("https://api.ipify.org?format=json");
    const d=await r.json();
    document.getElementById("ip-display").textContent=d.ip;
  }catch{
    document.getElementById("ip-display").textContent="Unavailable";
  }
}

// ── Overlay / Menu ──────────────────────────────────────────────
const overlay=document.getElementById("overlay");
const panelGroup=document.getElementById("panel-group");
document.getElementById("open-menu-btn").addEventListener("click",()=>{
  overlay.classList.add("show");
  panelGroup.classList.add("show");
});
overlay.addEventListener("click",()=>{
  overlay.classList.remove("show");
  panelGroup.classList.remove("show");
});

// ── Boot ────────────────────────────────────────────────────────
setTimeout(()=>{
  document.getElementById("loader").classList.add("hide");
  document.getElementById("app").classList.add("visible");
  initBattery();
  fetchIP();
},2000);
